     3	import java.util.HashSet;
     4	import java.util.Set;
     5	import java.util.stream.Collectors;
     6	
     7	public class GameOfLife {
     8	
     9	    private static final int MINIMUM_NEIGHBOURS_TO_SURVIVE = 2;
    10	    private static final int MAXIMUM_NEIGHBOURS_TO_SURVIVE = 3;
    11	    private static final int NEIGHBOURS_REQUIRED_FOR_BIRTH = 3;
    12	
    13	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
    14	        return candidates(livingCells).stream()
    15	                .filter(cell -> isAliveNextGeneration(cell, livingCells))
    16	                .collect(Collectors.toSet());
    17	    }
    18	
    19	    private Set<Cell> candidates(Set<Cell> livingCells) {
    20	        Set<Cell> candidates = new HashSet<>(livingCells);
    21	        livingCells.forEach(cell -> candidates.addAll(cell.neighbours()));
    22	        return candidates;
    23	    }
    24	
    25	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
    26	        int livingNeighbours = livingNeighbourCount(cell, livingCells);
    27	        return livingCells.contains(cell)
    28	                ? survives(livingNeighbours)
    29	                : isBorn(livingNeighbours);
    30	    }
    31	
    32	    private boolean survives(int livingNeighbours) {
    33	        return livingNeighbours >= MINIMUM_NEIGHBOURS_TO_SURVIVE
    34	                && livingNeighbours <= MAXIMUM_NEIGHBOURS_TO_SURVIVE;
    35	    }
    36	
    37	    private boolean isBorn(int livingNeighbours) {
    38	        return livingNeighbours == NEIGHBOURS_REQUIRED_FOR_BIRTH;
    39	    }
    40	
    41	    private int livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
    42	        return (int) cell.neighbours().stream()
    43	                .filter(livingCells::contains)
    44	                .count();
    45	    }
    46	}
